// Extract and transform flight data from OpenSky API response
const items = $input.all();
const outputItems = [];

for (const item of items) {
  const responseData = item.json;

  // Check if we have valid states data
  if (!responseData || !responseData.states || !Array.isArray(responseData.states)) {
    console.log('No valid states data received');
    continue;
  }

  const timestamp = responseData.time || Math.floor(Date.now() / 1000);
  const flights = [];

  // Transform each flight state into structured format
  for (const state of responseData.states) {
    // OpenSky API state array indices:
    // 0: icao24, 1: callsign, 2: origin_country, 3: time_position
    // 4: last_contact, 5: longitude, 6: latitude, 7: baro_altitude
    // 8: on_ground, 9: velocity, 10: true_track, 11: vertical_rate
    // 12: sensors, 13: geo_altitude, 14: squawk, 15: spi, 16: position_source

    const flight = {
      icao24: state[0] || null,
      callsign: (state[1] || '').trim() || null,
      origin_country: state[2] || null,
      time_position: state[3] || null,
      last_contact: state[4] || null,
      longitude: state[5] || null,
      latitude: state[6] || null,
      baro_altitude: state[7] || null,
      on_ground: state[8] || false,
      velocity: state[9] || null,
      true_track: state[10] || null,
      vertical_rate: state[11] || null,
      geo_altitude: state[13] || null,
      squawk: state[14] || null,
      spi: state[15] || false,
      position_source: state[16] || 0,
      // Add computed fields
      fetch_timestamp: timestamp,
      region: 'region1'
    };

    // Only include flights with valid position data
    if (flight.latitude !== null && flight.longitude !== null) {
      flights.push(flight);
    }
  }

  // Create snapshot object
  const snapshot = {
    timestamp: timestamp,
    datetime: new Date(timestamp * 1000).toISOString(),
    region: 'region1',
    region_name: 'Central Europe',
    bounding_box: {
      lamin: 45.0,
      lomin: 5.0,
      lamax: 55.0,
      lomax: 15.0
    },
    flight_count: flights.length,
    flights: flights,
    metadata: {
      api_status: 'success',
      fetch_method: 'n8n_workflow',
      workflow_execution: $execution.id
    }
  };

  outputItems.push({
    json: snapshot
  });

  console.log(`Processed ${flights.length} flights for region1`);
}

return outputItems;

// Load previous snapshot and detect anomalies
const fs = require('fs');
const path = require('path');

const items = $input.all();
const outputItems = [];

for (const item of items) {
  const currentSnapshot = item.json;
  let previousSnapshot = null;

  // Try to load previous snapshot
  const snapshotPath = '/data/flight_snapshots/region1_latest.json';
  try {
    if (fs.existsSync(snapshotPath)) {
      const previousData = fs.readFileSync(snapshotPath, 'utf8');
      previousSnapshot = JSON.parse(previousData);
    }
  } catch (error) {
    console.log('Could not load previous snapshot:', error.message);
  }

  // Detect anomalies by comparing current and previous snapshots
  const anomalies = [];

  if (previousSnapshot && previousSnapshot.flights) {
    const prevFlightMap = {};
    previousSnapshot.flights.forEach(f => {
      if (f.icao24) prevFlightMap[f.icao24] = f;
    });

    currentSnapshot.flights.forEach(currentFlight => {
      const prevFlight = prevFlightMap[currentFlight.icao24];

      if (prevFlight) {
        // Check for altitude change
        if (currentFlight.baro_altitude && prevFlight.baro_altitude) {
          const altChange = Math.abs(currentFlight.baro_altitude - prevFlight.baro_altitude);
          if (altChange > 500) {
            anomalies.push({
              type: 'rapid_altitude_change',
              icao24: currentFlight.icao24,
              callsign: currentFlight.callsign,
              severity: 'high',
              details: `Altitude changed by ${altChange.toFixed(0)}m`,
              current_altitude: currentFlight.baro_altitude,
              previous_altitude: prevFlight.baro_altitude
            });
          }
        }
      }

      // Check for low speed at high altitude
      if (currentFlight.velocity !== null && currentFlight.baro_altitude !== null) {
        if (currentFlight.velocity < 50 && currentFlight.baro_altitude > 8000) {
          anomalies.push({
            type: 'low_speed_at_altitude',
            icao24: currentFlight.icao24,
            callsign: currentFlight.callsign,
            severity: 'high',
            details: `Speed ${currentFlight.velocity.toFixed(1)} m/s at ${currentFlight.baro_altitude.toFixed(0)}m altitude`,
            velocity: currentFlight.velocity,
            altitude: currentFlight.baro_altitude
          });
        }
      }

      // Check for rapid descent
      if (currentFlight.vertical_rate !== null && currentFlight.vertical_rate < -15) {
        if (currentFlight.baro_altitude && currentFlight.baro_altitude > 1000) {
          anomalies.push({
            type: 'rapid_descent',
            icao24: currentFlight.icao24,
            callsign: currentFlight.callsign,
            severity: 'critical',
            details: `Descending at ${currentFlight.vertical_rate.toFixed(1)} m/s`,
            vertical_rate: currentFlight.vertical_rate,
            altitude: currentFlight.baro_altitude
          });
        }
      }

      // Check for stationary aircraft (very low speed)
      if (currentFlight.velocity !== null && currentFlight.velocity < 10 && !currentFlight.on_ground) {
        anomalies.push({
          type: 'stationary_aircraft',
          icao24: currentFlight.icao24,
          callsign: currentFlight.callsign,
          severity: 'medium',
          details: `Nearly stationary at ${currentFlight.velocity.toFixed(1)} m/s (not on ground)`,
          velocity: currentFlight.velocity,
          on_ground: currentFlight.on_ground
        });
      }
    });
  }

  // Add anomalies to snapshot
  currentSnapshot.anomalies = anomalies;
  currentSnapshot.anomaly_count = anomalies.length;

  outputItems.push({
    json: currentSnapshot
  });

  console.log(`Detected ${anomalies.length} anomalies in region1`);
}

return outputItems;

// Save anomalies to alerts file
const fs = require('fs');
const items = $input.all();

for (const item of items) {
  const snapshot = item.json;

  if (snapshot.anomalies && snapshot.anomalies.length > 0) {
    const alertsPath = '/data/alerts/active_alerts.json';
    let allAlerts = [];

    // Load existing alerts
    try {
      if (fs.existsSync(alertsPath)) {
        const existingData = fs.readFileSync(alertsPath, 'utf8');
        allAlerts = JSON.parse(existingData);
      }
    } catch (error) {
      console.log('Could not load existing alerts:', error.message);
    }

    // Add new anomalies with timestamps
    const newAlerts = snapshot.anomalies.map(anomaly => ({
      ...anomaly,
      timestamp: snapshot.timestamp,
      datetime: snapshot.datetime,
      region: snapshot.region,
      alert_id: `${anomaly.icao24}_${anomaly.type}_${snapshot.timestamp}`
    }));

    // Combine with existing alerts (keep last 100)
    allAlerts = [...newAlerts, ...allAlerts].slice(0, 100);

    // Write back to file
    const alertsData = {
      last_updated: snapshot.datetime,
      alert_count: allAlerts.length,
      alerts: allAlerts
    };

    fs.writeFileSync(alertsPath, JSON.stringify(alertsData, null, 2), 'utf8');
    console.log(`Saved ${newAlerts.length} new alerts to ${alertsPath}`);
  }
}

return items;

// Handle API failure - load cached snapshot
const fs = require('fs');
const snapshotPath = '/data/flight_snapshots/region1_latest.json';

let cachedSnapshot = null;

try {
  if (fs.existsSync(snapshotPath)) {
    const cachedData = fs.readFileSync(snapshotPath, 'utf8');
    cachedSnapshot = JSON.parse(cachedData);

    // Update metadata to indicate cache use
    if (cachedSnapshot.metadata) {
      cachedSnapshot.metadata.api_status = 'cached';
      cachedSnapshot.metadata.cache_reason = 'API request failed or rate limited';
      cachedSnapshot.metadata.cached_at = new Date().toISOString();
    }

    console.log('API failed - using cached snapshot from', cachedSnapshot.datetime);

    return [{ json: cachedSnapshot }];
  }
} catch (error) {
  console.log('Could not load cached snapshot:', error.message);
}

// If no cache available, return empty structure
return [{
  json: {
    timestamp: Math.floor(Date.now() / 1000),
    datetime: new Date().toISOString(),
    region: 'region1',
    region_name: 'Central Europe',
    flight_count: 0,
    flights: [],
    anomalies: [],
    anomaly_count: 0,
    metadata: {
      api_status: 'failed',
      cache_status: 'unavailable',
      error: 'No cached data available'
    }
  }
}];

// Create log entry
const items = $input.all();
const logEntries = [];

for (const item of items) {
  const snapshot = item.json;

  const logEntry = {
    timestamp: snapshot.datetime,
    region: snapshot.region,
    flight_count: snapshot.flight_count,
    anomaly_count: snapshot.anomaly_count || 0,
    api_status: snapshot.metadata?.api_status || 'unknown',
    workflow_id: $execution.id
  };

  const logLine = JSON.stringify(logEntry) + '\n';
  logEntries.push({ json: { data: logLine } });
}

return logEntries;
